const tasks = yield* Database.query(Filter.type(types['com.example.type.task'])).run;
const matches = tasks.filter((t) => typeof t.title === 'string' && t.title.toLowerCase().includes('docs'));
for (const t of matches) {
  Obj.update(t, (task) => { task.status = 'done'; });
}
yield* Database.flush();

const after = yield* Database.query(Filter.type(types['com.example.type.task'])).run;
const done = after.filter((t) => t.status === 'done');
yield* print('updated', matches.map((t) => t.title));
yield* print('done count', done.length, 'of', after.length);
